"use strict";function setDateTimeRangeForOTRequest(n){var i=new Date($("#FromDateOT").val()),r=new Date($("#ToDateOT").val()),t=$("#DateTime-Now").val();i=$.format.date(i,"dd MMM, yyyy");r=$.format.date(r,"dd MMM, yyyy");switch(parseInt(n)){case 1:r=i=Date.parse(t).toString("dd MMM, yyyy");break;case 2:r=i=Date.parse(t).add(-1).days().toString("dd MMM, yyyy");break;case 3:i=Date.parse(t).moveToDayOfWeek(0,-1).toString("dd MMM, yyyy");r=Date.parse(t).toString("dd MMM, yyyy");break;case 4:i=Date.parse(t).moveToDayOfWeek(0,-1).add(-7).days().toString("dd MMM, yyyy");r=Date.parse(t).moveToDayOfWeek(0,-1).add(-1).days().toString("dd MMM, yyyy");break;case 5:i=Date.parse(t).moveToFirstDayOfMonth().toString("dd MMM, yyyy");r=Date.parse(t).toString("dd MMM, yyyy");break;case 6:i=Date.parse(t).add(-1).months().moveToFirstDayOfMonth().toString("dd MMM, yyyy");r=Date.parse(t).add(-1).months().moveToLastDayOfMonth().toString("dd MMM, yyyy");break;case 7:i=Date.parse(t).add(-1).months().moveToFirstDayOfMonth().toString("dd MMM, yyyy");r=Date.parse(t).toString("dd MMM, yyyy")}$("#FromDateOT").val(i);$("#ToDateOT").val(r)}function loadOTRequestDetail(){$("#OTRequest .loading-process").fadeIn(300);$.post(_global.root+"overtime/OvertimeRequestDetail",$("#OTRequest #form").serialize(),function(n){$("#dataOTRequest tbody").html(n);floatThead("table#data");$("#OTRequest .loading-process").fadeOut(300)})}function initButtonForOTRequest(){$("#OTRequest #btn-submit").click(function(){$("#OTRequest #form #OvertimeId").val(null);loadOTRequestDetail()})}$(document).ready(function(){initAutocomplete("#OTRequest #CreatedName","#OTRequest #CreatedBy",!1);$("#OTRequest #Date").on("change",function(){setDateTimeRangeForOTRequest($(this).val())});loadOTRequestDetail();initButtonForOTRequest()});"use strict";